def extract_clean_text(text):
  """Extract the text excluding html tags, numbers and non alphabetic characters"""
  return''.join(re.sub('[^a-zA-Z]',' ',text).split())

def remove_stop_words(text):
  """Return a cleaned text excluding stop words"""
  text =''.join(word for word in extract_clean_text(text).split() if word not in stopwords.words('english'))
  return text

